    // We assume Compiler and ProcessingInstruction are available in the classpath.

    @Test
    public void testNullTest() {
        Node node = mock(Node.class);
        assertTrue(DOMNodePointer.testNode(node, null));
    }

    @Test
    public void testNodeNameTest_ElementNodeMismatch() {
        Node node = mock(Node.class);
        when(node.getNodeType()).thenReturn(Node.TEXT_NODE);
        NodeNameTest test = mock(NodeNameTest.class);
        assertFalse(DOMNodePointer.testNode(node, test));
    }

    @Test
    public void testNodeNameTest_WildcardNoPrefix() {
        Node node = mock(Node.class);
        when(node.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(true);
        when(test.getNodeName()).thenReturn(new QName("any"));
        when(test.getNamespaceURI()).thenReturn("uri");
        // If wildcard is true and prefix is null
        when(test.getNodeName().getPrefix()).thenReturn(null);

        assertTrue(DOMNodePointer.testNode(node, test));
    }

    @Test
    public void testNodeNameTest_WildcardMatch() {
        Node node = mock(Node.class);
        when(node.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        // Mocking static utility behavior via DOMNodePointer if possible, 
